<?php
namespace App\Http\Controllers\Admin; use App\Domain\Capabilities\{CapabilityDependencyInspector,CapabilityManager,CapabilityRegistry,CapabilityRelationManager,CapabilityViewData}; use App\Domain\Installation\WebsiteSettings; use App\Http\Controllers\{Controller,PublicSiteController}; use App\Http\Requests\Capabilities\SaveCapabilityRequest; use App\Models\{Capability,CapabilityCategory,Industry,Page,Product,Solution}; use Illuminate\Contracts\View\View; use Illuminate\Http\{RedirectResponse,Request,Response}; use Illuminate\Support\Carbon; use Illuminate\Support\Str; use Illuminate\Validation\Rule; class CapabilityController extends Controller { public function index(Request $request):View{$f=$request->validate(['search'=>['nullable','string','max:160'],'category'=>['nullable','integer'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without'],'template'=>['nullable',Rule::in(CapabilityRegistry::TEMPLATES)],'sort'=>['nullable','in:title,updated_at,published_at,display_order'],'direction'=>['nullable','in:asc,desc']]);$q=Capability::with('category')->withCount(['relatedSolutions','relatedProducts','relatedIndustries','relatedPages'])->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('title','like',"%$v%")->orWhere('slug','like',"%$v%")))->when($f['category']??null,fn($q,$v)=>$q->where('capability_category_id',$v))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when($f['template']??null,fn($q,$v)=>$q->where('template',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only')$q->whereNotNull('archived_at');elseif(($f['archived']??'without')==='without')$q->whereNull('archived_at');return view('admin.capabilities.index',['capabilities'=>$q->orderBy($f['sort']??'display_order',$f['direction']??'asc')->paginate(20)->withQueryString(),'f'=>$f,'categories'=>CapabilityCategory::orderBy('display_order')->get(),'templates'=>CapabilityRegistry::TEMPLATES]);} public function create():View{return $this->editor(new Capability);} public function store(SaveCapabilityRequest $request,CapabilityManager $manager):RedirectResponse{$item=$manager->save($request->validated(),null,$request->user()->id);return redirect()->route('admin.capabilities.edit',$item)->with('status','Draft capability created.');} public function edit(Capability $capability):View{return $this->editor($capability);} public function update(SaveCapabilityRequest $request,Capability $capability,CapabilityManager $manager):RedirectResponse{$manager->save($request->validated(),$capability,$request->user()->id);return back()->with('status','Capability saved.');} private function editor(Capability $item):View{if($item->exists)$item->load(['highlights','benefits','facts','relatedSolutions','relatedProducts','relatedIndustries','relatedPages']);return view('admin.capabilities.editor',['capability'=>$item,'categories'=>CapabilityCategory::where('is_active',true)->orderBy('display_order')->get(),'templates'=>CapabilityRegistry::TEMPLATES,'heroes'=>CapabilityRegistry::HERO_STYLES,'icons'=>CapabilityRegistry::ICONS,'solutions'=>Solution::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'products'=>Product::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'industries'=>Industry::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'pages'=>Page::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'dependencies'=>$item->exists?app(CapabilityDependencyInspector::class)->inspect($item):null]);} public function publish(Capability $capability,CapabilityManager $manager):RedirectResponse{$manager->publish($capability);return back()->with('status','Capability published.');} public function schedule(Request $request,Capability $capability,CapabilityManager $manager):RedirectResponse{$value=$request->validate(['scheduled_for'=>['required','date']]);$timezone=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$manager->schedule($capability,Carbon::parse($value['scheduled_for'],$timezone)->utc()->toDateTimeString());return back()->with('status','Capability scheduled.');} public function unpublish(Capability $capability,CapabilityManager $manager):RedirectResponse{$manager->unpublish($capability);return back();} public function archive(Capability $capability,CapabilityManager $manager):RedirectResponse{$manager->archive($capability);return back();} public function restore(Capability $capability,CapabilityManager $manager):RedirectResponse{$manager->restore($capability);return back();} public function duplicate(Request $request,Capability $capability,CapabilityManager $manager):RedirectResponse{return redirect()->route('admin.capabilities.edit',$manager->duplicate($capability,$request->user()->id));} public function move(Capability $capability,string $direction,CapabilityManager $manager):RedirectResponse{$manager->move($capability,$direction);return back();} public function relations(Request $request,Capability $capability,CapabilityRelationManager $manager):RedirectResponse{$d=$request->validate(['related_solution_ids'=>['array','max:8'],'related_solution_ids.*'=>['integer','distinct','exists:solutions,id'],'related_product_ids'=>['array','max:8'],'related_product_ids.*'=>['integer','distinct','exists:products,id'],'related_industry_ids'=>['array','max:8'],'related_industry_ids.*'=>['integer','distinct','exists:industries,id'],'related_page_ids'=>['array','max:6'],'related_page_ids.*'=>['integer','distinct','exists:pages,id']]);$manager->sync($capability,$d['related_solution_ids']??[],$d['related_product_ids']??[],$d['related_industry_ids']??[],$d['related_page_ids']??[]);return back();} public function preview(Request $request,Capability $capability,CapabilityViewData $data):Response{return response()->view('capabilities.show',['capability'=>$data->preview($capability),'preview'=>true]+app(PublicSiteController::class)->sharedViewData($request))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');} public function categories():View{return view('admin.capabilities.categories',['categories'=>CapabilityCategory::withCount('capabilities')->orderBy('display_order')->get()]);} public function storeCategory(Request $request,CapabilityManager $manager):RedirectResponse{$manager->saveCategory($this->categoryData($request));return back();} public function updateCategory(Request $request,CapabilityCategory $category,CapabilityManager $manager):RedirectResponse{$manager->saveCategory($this->categoryData($request,$category),$category);return back();} public function moveCategory(CapabilityCategory $category,string $direction,CapabilityManager $manager):RedirectResponse{$manager->moveCategory($category,$direction);return back();} private function categoryData(Request $request,?CapabilityCategory $category=null):array{$raw=(string)$request->input('slug');$request->merge(['slug'=>(str_contains($raw,'/')||str_contains($raw,'\\')||str_contains($raw,'..'))?'':Str::slug(Str::lower($raw)),'is_active'=>$request->boolean('is_active')]);return $request->validate(['name'=>['required','string','max:120'],'slug'=>['required','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/',Rule::unique('capability_categories')->ignore($category)],'description'=>['nullable','string','max:2000'],'is_active'=>['boolean']]);} }
